      const arr = bySession.get(n.session_id) ?? [];
      arr.push(n.id);
      bySession.set(n.session_id, arr);
    }
    if (n.head_sha) {
      const arr = bySha.get(n.head_sha) ?? [];
      arr.push(n.id);
      bySha.set(n.head_sha, arr);
    }
  }
  for (const b of bugs) {
    if (b.origin_session) {
      for (const id of bySession.get(b.origin_session) ?? []) mark[id] = " <-- BUG";
    }
    if (b.origin_commit) {
      for (const id of bySha.get(b.origin_commit) ?? []) mark[id] = " <-- BUG";
    }
  }
}

